insert into public.content_items (content_type,title,slug,route,excerpt,body,category,seo_title,seo_description,status,sort_order,data) values
('case_study', 'Palazzo Lakeside Hotel', 'palazzo-lakeside-hotel', '/case-studies/palazzo-lakeside-hotel/', 'A hotel-booking website for a lakeside family stay, presenting the property and helping visitors move towards a reservation.', 'The project centres on a digital booking experience for Palazzo Lakeside Hotel, a family-oriented property known for its setting near Lake Cecile. The website story focuses on presenting the stay clearly and making the booking journey easier to understand. A property-led web experience that organises hotel information and supports a straightforward path from discovery to booking. The portfolio description identifies this as a hotel booking website. Technologies identified in the available project description: TypeScript, Node.js, MongoDB. Additional technologies have not been inferred.', 'Hospitality & travel', 'Palazzo Lakeside Hotel — Selected Project Experience | ONLYUSLABS', 'Project context and technology details for Palazzo Lakeside Hotel.', 'draft', 10, '{"project_type": "Hotel booking website", "industry": "Hospitality & travel", "technologies": ["TypeScript", "Node.js", "MongoDB"], "portfolio_attribution": "Previous portfolio engagement; confirm project-specific delivery scope before publishing as an ONLYUSLABS client reference."}'::jsonb),
('case_study', 'Zenith Holidays', 'zenith-holidays', '/case-studies/zenith-holidays/', 'A travel website built around the varied holiday needs of Indian travellers and a broad range of holiday packages.', 'Zenith Holidays is presented as an online travel company serving different travel needs across India. Its portfolio description highlights holiday packages designed for multiple traveller segments. A travel-focused digital experience designed to communicate destination and package options clearly, while giving visitors a coherent starting point for planning a trip. Technologies identified in the available project description: Next.js, TypeScript, Node.js. Additional technologies have not been inferred.', 'Travel & tourism', 'Zenith Holidays — Selected Project Experience | ONLYUSLABS', 'Project context and technology details for Zenith Holidays.', 'draft', 20, '{"project_type": "Online travel company website", "industry": "Travel & tourism", "technologies": ["Next.js", "TypeScript", "Node.js"], "portfolio_attribution": "Previous portfolio engagement; confirm project-specific delivery scope before publishing as an ONLYUSLABS client reference."}'::jsonb),
('case_study', 'The Block Hotel & Commons', 'the-block-hotel', '/case-studies/the-block-hotel/', 'A booking website for a nature-oriented destination with access to outdoor activities such as skiing, hiking, biking, rafting and fishing.', 'The Block Hotel & Commons is described as a destination for guests who want to connect with nature. The portfolio summary references a range of outdoor activities, including skiing, hiking, biking, rafting and fishing. A destination-led booking experience that gives the property and its outdoor setting a clear digital presence. The available portfolio description identifies the project as a hotel booking website. Technologies identified in the available project description: Next.js, TypeScript, Node.js. Additional technologies have not been inferred.', 'Hospitality & outdoor travel', 'The Block Hotel & Commons — Selected Project Experience | ONLYUSLABS', 'Project context and technology details for The Block Hotel & Commons.', 'draft', 30, '{"project_type": "Hotel booking website", "industry": "Hospitality & outdoor travel", "technologies": ["Next.js", "TypeScript", "Node.js"], "portfolio_attribution": "Previous portfolio engagement; confirm project-specific delivery scope before publishing as an ONLYUSLABS client reference."}'::jsonb),
('case_study', 'Xecutables', 'xecutables', '/case-studies/xecutables/', 'An AI-driven SaaS concept connecting physical security, IT infrastructure, IoT and HR workflows across cloud and on-premises environments.', 'Xecutables is described as a platform that brings physical security and digital ecosystems together. Its stated scope connects physical security systems, IT infrastructure, IoT and HR workflows, with cloud and on-premises deployment contexts. A connected enterprise platform concept focused on bringing multiple operational systems into a more coordinated environment. The published project description identifies the application as AI-driven SaaS. Technologies identified in the available project description: Next.js, TypeScript, Node.js. Additional technologies have not been inferred.', 'Enterprise security & connected systems', 'Xecutables — Selected Project Experience | ONLYUSLABS', 'Project context and technology details for Xecutables.', 'draft', 40, '{"project_type": "AI-driven SaaS application", "industry": "Enterprise security & connected systems", "technologies": ["Next.js", "TypeScript", "Node.js"], "portfolio_attribution": "Previous portfolio engagement; confirm project-specific delivery scope before publishing as an ONLYUSLABS client reference."}'::jsonb),
('case_study', 'Sologix Energy', 'sologix-energy', '/case-studies/sologix-energy/', 'A solar installation business website with Razorpay payment integration for payment and order-processing workflows.', 'Sologix Energy is presented as a solar installation company focused on renewable-energy solutions. The public project description specifically notes the integration of Razorpay for secure payments and order processing. A business website supported by a payment flow, connecting the company’s solar offering with a practical online transaction experience. Technologies identified in the available project description: Next.js, TypeScript, Node.js, Razorpay. Additional technologies have not been inferred.', 'Energy & sustainability', 'Sologix Energy — Selected Project Experience | ONLYUSLABS', 'Project context and technology details for Sologix Energy.', 'draft', 50, '{"project_type": "Solar installation company website", "industry": "Energy & sustainability", "technologies": ["Next.js", "TypeScript", "Node.js", "Razorpay"], "portfolio_attribution": "Previous portfolio engagement; confirm project-specific delivery scope before publishing as an ONLYUSLABS client reference."}'::jsonb),
('case_study', 'Dezine Expert', 'dezine-expert', '/case-studies/dezine-expert/', 'An AI-assisted, integrated application concept for architecture, engineering and construction professionals.', 'Dezine Expert is described as an intelligent, AI-assisted and integrated application for AEC professionals. The available portfolio summary positions it around the needs of architecture, engineering and construction workflows. A domain-focused digital application concept designed around the working context of AEC professionals, with AI assistance as part of the product proposition. Technologies identified in the available project description: React, TypeScript, Node.js. Additional technologies have not been inferred.', 'Architecture, engineering & construction', 'Dezine Expert — Selected Project Experience | ONLYUSLABS', 'Project context and technology details for Dezine Expert.', 'draft', 60, '{"project_type": "AI-assisted AEC application", "industry": "Architecture, engineering & construction", "technologies": ["React", "TypeScript", "Node.js"], "portfolio_attribution": "Previous portfolio engagement; confirm project-specific delivery scope before publishing as an ONLYUSLABS client reference."}'::jsonb)
